const items = $input.first().json.data.products.items;
const webhookItem = $('Webhook ERP Stock').first();
let rawPayload = webhookItem.json.body;

if (!rawPayload && webhookItem.binary && webhookItem.binary.data) {
  const buf = Buffer.from(webhookItem.binary.data.data, 'base64');
  rawPayload = JSON.parse(buf.toString('utf-8'));
} else if (typeof rawPayload === 'string') {
  rawPayload = JSON.parse(rawPayload);
}

const itemCode = rawPayload.item_code;
const actualQty = rawPayload.actual_qty;

const matched = items.find(i => i.sku === itemCode);
if (!matched) {
  throw new Error(`Produto com SKU ${itemCode} não encontrado no EverShop`);
}

return [{
  json: {
    sku: itemCode,
    uuid: matched.uuid,
    actual_qty: Math.max(0, Math.floor(actualQty))
  }
}];
